"""The King of Fighters '95 Full Cart (Sega Saturn) builder, version 2.1.0-beta.1.

Builds a Saturn cartridge image holding the whole game from your own dumps:

    python3 kof95_cart.py <disc> <mpr-18811-mx.ic1> [kof95.zip] [output_dir]

    disc               The King of Fighters '95 (Japan), T-3101G (any Japanese pressing: only track 01 is read):
                       its .cue (with its .bin tracks, or one .bin), its track 01 alone as a raw .bin, or an .iso
    mpr-18811-mx.ic1   the 2 MiB ROM cartridge sold with the game
    kof95.zip          optional: the Neo Geo MVS ROM set of The King of Fighters '95 (MAME name kof95; 084-m1.m1,
                       084-v1.v1, 084-v2.v2 and 084-v3.v3 are read)

With kof95.zip: a 48 MiB cartridge with the Neo Geo music, sound effects and voices built in; the game needs no CD.
Writes kof95_cart.ss (Mednafen) and kof95_cart_48M.bin (MiSTer), the same image.
Without it: a 32 MiB cartridge with the sound effects of the Saturn release; the game plays its music from the audio
tracks of the disc in the drive: the Saturn disc, or the Neo Geo CD or PlayStation disc of the game for their orchestral
arranged music (the cartridge recognises them); without a disc, no music. Writes kof95_cart_cd_audio.ss (Mednafen) and
kof95_cart_cd_audio_32M.bin (MiSTer).
Both have the same speed and fixes; the third argument is the MVS set when it is a .zip file, otherwise the output_dir.
The image is checked against its reference SHA-256. Needs Python 3.8 or later, nothing else; PyPy (pypy.org) runs it
about 15 times faster (pypy3 kof95_cart.py ...). With kof95.zip, the music is rebuilt from the MVS sound program by an
emulated Z80, 23 pieces run in parallel on all cores: about 3 minutes with PyPy on a recent processor, 15 minutes to
2 hours with the usual Python; without it, about a minute.
KOF95_PROGRESS=1 replaces the progress bar by '@progress' lines (for the builder, the window).

This file contains only original code: the build modules and the assembled SH-2 code of the project. No data
from the game is included; everything is taken from your dumps at build time.
"""
