    ("init: count of the fixed wait 0x0600219C-0x060021AA (mov #8,r2)", 0x0600219C, 0x0600219E),
    ("sound init 0x06025D44: wait for the slave after command 6 (bt 0x06025D78)", 0x06025D7C, 0x06025D7E),
