# Optional detours, applied only if the ELF defines the symbol (option off = image unchanged):
# symbol -> (literal address, original long, {address: (original, new) 16-bit words}).
MM_OPT_DETOURS = {
    # CHAR_RAW: group handler 0x060072D0 of the tile cache -> char_raw (docs/archive/patterns_raw.md).
    # "mov #-4,r0; mov.l @(r0,r10),r0; cmp/ge r0,r1; bt 0x06007274; shlr r1; add r10,r1" becomes
    # "mov.l @(1,PC),r0; jmp @r0; nop; nop; .long char_raw"; char_raw returns to 0x060072DC.
    "char_raw": (0x060072D8, 0x410131AC, {
        0x060072D0: (0xE0FC, 0xD001), 0x060072D2: (0x00AE, 0x402B),
        0x060072D4: (0x3103, 0x0009), 0x060072D6: (0x89CD, 0x0009),
    }),
    # MENU_RAW: decompression of 8 groups of 003F.PRS in 0x060077A8 (menus) -> menu_raw (docs/archive/clean_image.md);
    # menu_raw returns to 0x060077E0.
    "menu_raw": (0x060077D8, 0x396CDA9F, {
        0x060077D0: (0xD91C, 0xD001), 0x060077D2: (0x4601, 0x402B),
        0x060077D4: (0x369C, 0x0009), 0x060077D6: (0x6662, 0x0009),
        0x060077DC: (0xBD98, 0x0009), 0x060077DE: (0x4F22, 0x0009),
    }),
    # VOICE_IN_PLACE (docs/archive/mvs_music_integration.md §8): bank registration 0x0604A092 -> voice_dir, which
    # gives r8 the cart address of the bank. "mov.l @(0x0604A0E8),r0 (0x05A08C00); mov.l @r8+,r9" becomes
    # "mov.l @(0x0604A0E8),r0 (voice_dir); jmp @r0"; the delay slot is the original "mov #-1,r4" of 0x0604A0A8, and
    # voice_dir returns to 0x0604A0AA. The literal is read by 0x0604A0A4 only.
    "voice_dir": (0x0604A0E8, 0x05A08C00, {0x0604A0A6: (0x6986, 0x402B)}),
    # PRE_DECOR (docs/archive/journal.md §23.5): end of the request list reset 0x06006C54 of the tile
    # cache -> pre_hook, which adds the prefetch requests of the AOF dojo before the producers. "mov.l @(0x0A,PC),r10;
    # mov.l @(..),r1; mov.l @(..),r2; mov.l r1,@r9; mov.l r2,@r10" becomes "mov.l @(0x0A,PC),r0; ...; jmp @r0; nop";
    # pre_hook does the two stores and returns like the original (lds.l @r15+,pr; rts). The literal 0x06006CD4 is read
    # by 0x06006CA8 only; no branch enters 0x06006CA6-0x06006CB6; 0x06006C54 is called by 0x06006C0A only.
    "pre_hook": (0x06006CD4, 0x0604AF54, {
        0x06006CA8: (0xDA0A, 0xD00A), 0x06006CAE: (0x2912, 0x402B), 0x06006CB0: (0x2A22, 0x0009),
    }),
}
