    # byte 0x060CC001; -1 written to it), becomes "mov.l @(0x06007F40),r0; jmp @r0; nop; literal" to ve_wait, which also
    # applies the command of a frame that starts meanwhile, writes the -1, sets r12 = 26 and goes to the slice loop 0x06007F68.
