CODES = ['%02x' % c for c in list(range(0x21, 0x2F)) + [0x30, 0x31] + list(range(0x33, 0x3A))]
SITES_FNS, B00_SIG = (0x176, 0x1C8, 0x1F0), bytes.fromhex('20fc72a0')

STEPS = ['capturing the music', 'converting the music', 'sound effects', 'compacting the data track',
         'stage tiles and voices', 'patching the game', 'building the image', 'decompressing the tiles',
         'order-screen taunts', 'music player and sounds', 'background tiles', 'checking the image']
STEPS_CD = STEPS[3:9] + ['slave program', 'background tiles', 'checking the image']   # without kof95.zip
LOG = io.StringIO()
STATE = {'step': 0, 't0': time.monotonic(), 't': time.monotonic(), 'progress': None, 'live': 0, 'said': 0.0}
SAY = threading.Lock()
TTY = sys.stderr.isatty()
MACHINE = os.environ.get('KOF95_PROGRESS') == '1'   # for the builder (the window): '@progress' lines instead of the bar
BAR = 24

def clock(s):
    s = int(s)
    return f'{s // 3600}:{s // 60 % 60:02d}:{s % 60:02d}' if s >= 3600 else f'{s // 60}:{s % 60:02d}'

def fraction():
    # Fraction of the current step's work done, or None when the step cannot be measured.
    if STATE['progress']:
        try:
            return max(0.0, min(1.0, STATE['progress']()))
        except Exception:
            pass
    return None

def status():
    # One line: the step, a bar measured from the work actually done in it (or a moving bar when the step cannot be
    # measured), the time since the start.
    n, now, f = STATE['step'], time.monotonic(), fraction()
    if f is None:
        k = int(now * 4) % (BAR + 3)
        bar, pct = ('░' * BAR + '█' * 3 + '░' * BAR)[BAR + 3 - k:2 * BAR + 3 - k], '    '
    else:
        bar, pct = '█' * int(f * BAR) + '░' * (BAR - int(f * BAR)), f'{f * 100:3.0f}%'
    return f'[{n:2}/{len(STEPS)}] {STEPS[n - 1]:<26} {bar} {pct}   {clock(now - STATE["t0"])}'

def show(force=False):
    # Rewrite the status line (terminal), or print it once a minute (file or pipe). The caller holds SAY.
    if not STATE['step']:
        return
    now = time.monotonic()
    if MACHINE:
        # @progress <step> <steps> <fraction of the step, -1 if unknown> <seconds since the start> <step name>
        f = fraction()
        print(f'@progress {STATE["step"]} {len(STEPS)} {-1 if f is None else f:.4f} {now - STATE["t0"]:.0f} '
              f'{STEPS[STATE["step"] - 1]}', file=sys.stderr, flush=True)
    elif TTY:
        line = status()
        print('\r' + line.ljust(STATE['live']), end='', file=sys.stderr, flush=True)
        STATE['live'] = len(line)
    elif force or now - STATE['said'] >= 60:
        print(status(), file=sys.stderr, flush=True)
        STATE['said'] = now

def ticker():
    while True:
        time.sleep(0.25)
        with SAY:
            show()

def say(line):
    # A line that stays (header, result, error), printed below the status line.
    with SAY:
        if STATE['live']:
            print('\r' + ' ' * STATE['live'] + '\r', end='', file=sys.stderr)
            STATE['live'] = 0
        print(line, file=sys.stderr, flush=True)

def go(name, progress=None):
    step(STEPS.index(name) + 1, progress)

def step(n, progress=None):
    # Start step n; progress: a function giving the fraction of its work done. Step times go to the log.
    with SAY:
        now = time.monotonic()
        if STATE['step']:
            LOG.write(f'  step {STATE["step"]} took {clock(now - STATE["t"])}\n')
        LOG.write(f'[{n}/{len(STEPS)}] {STEPS[n - 1]} (at {clock(now - STATE["t0"])})\n')
        STATE.update(step=n, t=now, progress=progress)
        show(force=True)

def finish():
    with SAY:
        if STATE['step']:
            LOG.write(f'  step {STATE["step"]} took {clock(time.monotonic() - STATE["t"])}\n')
        STATE['step'] = 0
        if STATE['live']:
            print('\r' + ' ' * STATE['live'] + '\r', end='', file=sys.stderr, flush=True)
            STATE['live'] = 0

class CountingPool:
    # multiprocessing.Pool for char_raw, counting the finished jobs; same results in the same order.
    def __init__(self, n):
        import multiprocessing
        self.pool, self.done, self.total = multiprocessing.Pool(n), 0, 0

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return self.pool.__exit__(*exc)

    def map(self, fn, items):
        items = list(items)
        self.total, out = len(items), []
        for r in self.pool.imap(fn, items):
            out.append(r)
            self.done = len(out)
        return out

def unpack(text):
    return zlib.decompress(base64.b64decode(text))

def save(path, data):
    # Write and close at once (PyPy closes a file left open only when its garbage collector runs).
    with open(path, 'wb' if isinstance(data, (bytes, bytearray)) else 'w') as f:
        f.write(data)

def load_modules(sources, folder):
    """Write the modules to a folder and import the ones run in this process (real files: subprocesses run the others)."""
    for name, src in sources.items():
        sys.modules.pop(name, None)
        with open(os.path.join(folder, name + '.py'), 'w', encoding='utf-8') as f:
            f.write(src)
    sys.path.insert(0, folder)
    importlib.invalidate_caches()
    return {n: importlib.import_module(n) for n in sources if n not in ('z80', 'm1_capture', 'ym2610_scsp', 'ym_loop')}

def call(mod, *argv):
    """Run a module's command-line entry point, its output going to the log."""
    old = sys.argv
    sys.argv = [mod.__name__ + '.py', *argv]
    try:
        r = mod.main()
    finally:
        sys.argv = old
        gc.collect()                            # PyPy: close (and flush) the files the module left open
    if r:
        raise RuntimeError(f'{mod.__name__} failed ({r})')

def music(m, mods, mvs, t, log):
    """The music package: each piece captured from the MVS sound program (Z80 in Python), converted for the Saturn."""
    cap = os.path.join(t, 'capture')
    z = zipfile.ZipFile(mvs)
    vrom = bytearray(0x900000)
    for name, off in (('084-v1.v1', 0), ('084-v2.v2', 0x400000), ('084-v3.v3', 0x800000)):
        b = z.read(name)
        vrom[off:off + len(b)] = b
    save(os.path.join(t, 'vrom.bin'), vrom)
    for c in CODES:
        os.makedirs(os.path.join(cap, c))
        save(os.path.join(cap, c, 'out.txt'), f'SNDSEQ f=767 v={c}\n')
    workers = max(1, min(len(CODES), os.cpu_count() or 1))
    log.write(f'music capture: {workers} at a time\n')
    outs = {}
    total = (828 * 67584 + 420 * 4000000) / 4000000      # emulated seconds of a capture (m1_capture: fin)

    def done():
        # Each ym.log line starts with the emulated time of the write: the last one says how far that capture is.
        s = 0.0
        for c in CODES:
            if c in outs:
                s += 1
                continue
            try:
                with open(os.path.join(cap, c, 'ym.log'), 'rb') as f:
                    f.seek(0, 2)
                    f.seek(max(0, f.tell() - 256))
                    lines = f.read().split(b'\n')
                s += min(0.999, float(lines[-2].split()[0]) / total) if len(lines) > 1 else 0
            except (OSError, ValueError, IndexError):
                pass
        return s / len(CODES)
    step(1, done)

    def one(c):
        r = subprocess.run([sys.executable, os.path.join(mods, 'm1_capture.py'), mvs, c, os.path.join(cap, c, 'ym.log')],
                           capture_output=True, text=True, encoding='utf-8', errors='replace')
        if r.returncode:
            raise RuntimeError(f'music capture {c}: {r.stderr.strip()[-2000:]}')
        return r.stdout
    with concurrent.futures.ThreadPoolExecutor(workers) as ex:
        futures = {ex.submit(one, c): c for c in CODES}
        try:
            for f in concurrent.futures.as_completed(futures):
                outs[futures[f]] = f.result()
        except BaseException:
            for f in futures:                   # Ctrl-C or a failed capture: start no other piece
                f.cancel()
            raise
    for c in CODES:
        log.write(outs[c])
    font = os.path.join(t, 'font.bin')
    save(font, unpack(VERSIONS['arcade']['font']))
    os.environ.update(YMSC_ADPCM='1', JUKE_CAPTURE=cap, JUKE_VROM=os.path.join(t, 'vrom.bin'), JUKE_FONT=font)
    m['juke'].C, m['juke'].V = os.path.join(cap, ''), os.path.join(t, 'vrom.bin')   # (read by juke at import time)
    package = os.path.join(t, 'package', 'package.bin')
    os.makedirs(os.path.dirname(package))
    ymsc = os.path.join(t, 'package', 'ymsc')               # juke writes one .ymsc per piece there, once converted
    step(2, lambda: len([n for n in os.listdir(ymsc) if n.endswith('.ymsc')]) / len(CODES))
    call(m['juke'], package)
    return package

SYNC = b'\x00' + b'\xff' * 10 + b'\x00'

def disc_cue(path, t):
    """A cue sheet for the build modules, which read only the first MODE1/2352 track: the .cue itself, or one made in t
    for a raw .bin (track 01 alone, or the whole disc in one file: track 01 comes first) or for an .iso (2048-byte
    sectors: put back into raw sectors; nothing reads their EDC/ECC)."""
    if path.lower().endswith('.cue'):
        return path
    d = os.path.join(t, 'disc')
    os.makedirs(d)
    size = os.path.getsize(path)
    with open(path, 'rb') as f:
        head = f.read(16)
    if size % 2352 == 0 and head[:12] == SYNC:
        track = os.path.abspath(path)
    elif size % 2048 == 0 and head[:12] != SYNC:
        track = os.path.join(d, 'track01.bin')
        with open(path, 'rb') as f, open(track, 'wb') as o:
            lba = 0
            while True:
                data = f.read(2048)
                if not data:
                    break
                m_, s_, f_ = (lba + 150) // 4500, (lba + 150) // 75 % 60, (lba + 150) % 75
                bcd = bytes((x // 10 << 4 | x % 10) for x in (m_, s_, f_))
                o.write(SYNC + bcd + b'\x01' + data.ljust(2048, b'\0') + bytes(288))
                lba += 1
    else:
        raise RuntimeError(f'{path}: neither a .cue, a raw 2352-byte .bin nor a 2048-byte .iso')
    cue = os.path.join(d, 'disc.cue')
    with open(cue, 'w', encoding='utf-8') as f:
        f.write(f'FILE "{track}" BINARY\n  TRACK 01 MODE1/2352\n    INDEX 01 00:00:00\n')
    return cue

def build(cue, rom, mvs, out_dir):
    """mvs: kof95.zip (48 MiB image, Neo Geo sound) or None (32 MiB image, Saturn sound and CD music)."""
    global STEPS
    a = VERSIONS['arcade']
    v = a if mvs else VERSIONS['cd']
    if mvs:
        names = zipfile.ZipFile(mvs).namelist()
        for name in ('084-m1.m1', '084-v1.v1', '084-v2.v2', '084-v3.v3'):
            if name not in names:
                raise RuntimeError(f'{mvs}: {name} missing (MVS ROM set kof95 expected)')
    else:
        STEPS = STEPS_CD
    os.makedirs(out_dir, exist_ok=True)
    stem = 'kof95_cart' if mvs else 'kof95_cart_cd_audio'
    ss = os.path.join(out_dir, stem + '.ss')
    log = LOG
    with tempfile.TemporaryDirectory() as t:
        mods = os.path.join(t, 'modules')
        os.makedirs(mods)
        m = load_modules(a['modules'], mods)
        boot, elf = os.path.join(t, 'boot.bin'), os.path.join(t, 'cdrom.elf')
        save(boot, unpack(v['boot']))
        save(elf, unpack(v['elf']))
        p = os.path.join(t, 'p')
        disc = disc_cue(cue, t)
        cue = os.path.join(t, 'compact', 'compact.cue')
        ss_c2, raw, clean = (os.path.join(t, n) for n in ('c2.ss', 'raw.ss', 'clean.ss'))
        blobs = os.path.join(t, 'blobs.txt')
        with contextlib.redirect_stdout(log):
            if mvs:
                package = music(m, mods, mvs, t, log)
                go('sound effects')
                os.environ['SFX_CACHE'] = '1'     # sample addresses in the cached CS1 area (journal §38.13)
                call(m['sound_effects'], disc, mvs, os.path.join(t, 'sfx'))
            go('compacting the data track')
            call(m['compact_track'], disc, rom, os.path.join(t, 'compact'), '--strip')
            go('stage tiles and voices')
            call(m['precompute_decors'], '--sat', '--source', disc, cue, os.path.join(t, 'decors'))
            call(m['voice_banks'], cue, os.path.join(t, 'voice'))
            go('patching the game')
            fusion = os.path.join(t, 'fusion.txt')   # native compare and branch in the translated code (tools/sh2opt)
            save(fusion, a['fusion'].encode())
            os.environ['SH2OPT'] = fusion
            call(m['patch_kof95'], cue, elf, p)
            with open(blobs, 'w') as f:
                for d in ('decors', 'voice', 'p'):
                    f.write(open(os.path.join(t, d, 'blobs.txt')).read())
            go('building the image')
            call(m['build_cart'], cue, rom, boot, ss_c2, '--run-from-cart', '--replace', '0=' + os.path.join(p, '0'),
                 '--replace', 'MM.BIN=' + os.path.join(p, 'MM.BIN'), '--blobs', blobs,
                 '--table', os.path.join(t, 'file_table.tsv'))
            pool = []
            def counting(n):
                pool.append(CountingPool(n))
                return pool[-1]
            m['char_raw'].Pool = counting
            go('decompressing the tiles', lambda: pool[0].done / pool[0].total)
            raw_log = io.StringIO()
            with contextlib.redirect_stdout(raw_log):
                call(m['char_raw'], ss_c2, os.path.join(t, 'file_table.tsv'), elf, raw, '--blobs', blobs,
                     '--source', disc, '--free-mpr', '--dedup')
            log.write(raw_log.getvalue())
            with open(os.path.join(t, 'char_raw.log'), 'w') as f:
                f.write(raw_log.getvalue())
            go('order-screen taunts')
            call(m['taunt'], raw, elf, os.path.join(t, 'char_raw.log'), clean)
            go('music player and sounds' if mvs else 'slave program')
            d = bytearray(open(clean, 'rb').read())
            mus = unpack(v['mus'])
            o = v['mus_code'] - 0x02000000
            if len(d) != 32 << 20 or any(b != d[o] for b in d[o:o + len(mus)]):
                raise RuntimeError('cartridge image: unexpected layout')
            d[o:o + len(mus)] = mus
            if mvs:
                pq = open(package, 'rb').read()
                br = open(os.path.join(t, 'sfx', 'sfx.bin'), 'rb').read()
                if len(pq) > 0x800000 or 0x800000 + len(br) > (16 << 20) - 1:
                    raise RuntimeError('music package or sound effects too large')
                d += pq + b'\xff' * (0x800000 - len(pq)) + br
                bases = []
                i = d.find(B00_SIG)
                while i >= 0:
                    b = i - SITES_FNS[0]
                    if all(d[b + x:b + x + 4] == B00_SIG for x in SITES_FNS):
                        bases.append(b)
                    i = d.find(B00_SIG, i + 1)
                if len(bases) != 1 or d[bases[0] + 0x184:bases[0] + 0x186] != b'\x02\x88':
                    raise RuntimeError('sound driver B00.PAC not found')
                d[bases[0] + 0x185] = 0xA8          # timer A of the sound driver: voices in time with the picture
                for x in SITES_FNS:
                    d[bases[0] + x + 3] = 0xB8      # pitch of three channels
                d += b'\xff' * ((48 << 20) - len(d))
            save(ss, d)
            go('background tiles')
            if mvs:
                call(m['vdp2_cells'], ss)
            else:                                   # in the free room of the 32 MiB, the heaviest decors first
                call(m['vdp2_cells'], ss, '--fit', '--order', v['cell_order'])
        sys.path.remove(mods)
    go('checking the image')
    data = open(ss, 'rb').read()
    mister = os.path.join(out_dir, stem + ('_48M.bin' if mvs else '_32M.bin'))
    save(mister, data)
    sums = [hashlib.sha256(open(path, 'rb').read()).hexdigest() for path in (ss, mister)]
    finish()
    say(f'done in {clock(time.monotonic() - STATE["t0"])}')
    ok = True
    for path, ref, h in zip((ss, mister), v['sha'], sums):
        good = h == ref
        ok &= good
        print(f'{path}: {"OK, identical to the reference" if good else "DIFFERENT from the reference " + ref[:16]}')
    return ok

def main():
    args = sys.argv[1:]
    if len(args) not in (2, 3, 4) or (len(args) == 4 and not args[2].lower().endswith('.zip')):
        print(__doc__)
        return 1
    if not sys.flags.utf8_mode:
        # Run again in UTF-8 mode, the build's subprocesses too (PYTHONUTF8): on Windows the console code page
        # cannot carry the text the build modules print.
        p = subprocess.Popen([sys.executable, '-X', 'utf8', os.path.abspath(__file__), *args],
                             env={**os.environ, 'PYTHONUTF8': '1'})
        while True:
            try:
                return p.wait()
            except KeyboardInterrupt:           # Ctrl-C reaches the build too: let it stop and write its log
                pass
    cue, rom, rest = args[0], args[1], args[2:]
    mvs = rest.pop(0) if rest and rest[0].lower().endswith('.zip') else None   # without it: 32 MiB, CD audio
    out = rest[0] if rest else '.'
    head = (f'kof95_cart.py 2.1.0-beta.1, Python {platform.python_version()} on {platform.platform()}, '
            f'{os.cpu_count()} processor threads')
    print(head, file=sys.stderr)
    LOG.write(head + '\n')
    threading.Thread(target=ticker, daemon=True).start()
    try:
        ok = build(cue, rom, mvs, out)
        code = 0 if ok else 3
    except BaseException as e:
        code = 130 if isinstance(e, KeyboardInterrupt) else 2
        n = STATE['step']
        where = f' at step {n}/{len(STEPS)} ({STEPS[n - 1]})' if n else ''
        finish()
        say(f'error{where}: {"interrupted" if code == 130 else e}')
        LOG.write(f'error{where}, after {clock(time.monotonic() - STATE["t0"])}:\n{traceback.format_exc()}')
    path = os.path.join(out, 'kof95_cart.log')
    try:
        os.makedirs(out, exist_ok=True)
        with open(path, 'w', encoding='utf-8') as f:
            f.write(LOG.getvalue())
        if code:
            print(f'details in {path} (please attach this file when you report the error)', file=sys.stderr)
    except OSError:
        pass
    return code

if __name__ == '__main__':
    sys.exit(main())
